package com.eelab.rflab.protocol

import java.util.Random
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Reference vectors generated by compiling the real `firmware/src/transport.c`
 * into a host harness and calling `transport_cobs_encode`. The expected
 * "body" values below are the encoder's output with the trailing `0x00` wire
 * delimiter removed, which is exactly what [Cobs.encode] returns.
 */
class CobsTest {

    @Test
    fun emptyInputEncodesToSingleCodeByte() {
        assertArrayEquals(hex("01"), Cobs.encode(ByteArray(0)))
        assertArrayEquals(ByteArray(0), Cobs.decode(hex("01")))
    }

    @Test
    fun matchesFirmwareVectors() {
        val vectors = listOf(
            "" to "01",
            "00" to "0101",
            "11" to "0211",
            "000000" to "01010101",
            "11220033" to "0311220233",
            "00010200" to "0103010201",
            "5a24" to "035a24",
            "f4ac07e24f" to "06f4ac07e24f",
            "6e624b002564eacead46a383fa007c2fa9" to
                "046e624b0a2564eacead46a383fa047c2fa9",
            "56b60aa70d9b13d0250800b10000a0d104b200f40093ebc8df9e0d46909e600039072f1152520017" to
                "0b56b60aa70d9b13d0250802b10105a0d104b202f40b93ebc8df9e0d46909e600739072f1152520217",
            "313233343536373839" to "0a313233343536373839",
        )
        for ((inputHex, expectedBodyHex) in vectors) {
            val input = hex(inputHex)
            val encoded = Cobs.encode(input)
            assertEquals("encoding $inputHex", expectedBodyHex, encoded.toHex())
            assertArrayEquals("decoding $inputHex", input, Cobs.decode(encoded))
        }
    }

    @Test
    fun embeddedZeroBytesBecomeGroupBoundaries() {
        val input = hex("110022")
        assertArrayEquals(hex("02110222"), Cobs.encode(input))
        assertArrayEquals(input, Cobs.decode(hex("02110222")))
    }

    @Test
    fun zerosAtEdgesRoundTrip() {
        for (input in listOf(
            hex("00"),
            hex("0011"),
            hex("1100"),
            hex("001100"),
            hex("000000"),
        )) {
            val encoded = Cobs.encode(input)
            assertArrayEquals(input, Cobs.decode(encoded))
        }
    }

    @Test
    fun fullGroupOf254NonZeroBytesUsesMaxCode() {
        val input = ByteArray(254) { 0xAA.toByte() }
        val encoded = Cobs.encode(input)

        assertEquals(256, encoded.size)
        assertEquals(0xFF.toByte(), encoded[0])
        for (i in 1..254) {
            assertEquals(0xAA.toByte(), encoded[i])
        }
        // Empty final group: a lone 0x01 code byte.
        assertEquals(0x01.toByte(), encoded[255])
        assertArrayEquals(input, Cobs.decode(encoded))
    }

    @Test
    fun runOf255NonZeroBytesSpillsIntoSecondGroup() {
        val input = ByteArray(255) { 0xAA.toByte() }
        val encoded = Cobs.encode(input)

        assertEquals(257, encoded.size)
        assertEquals(0xFF.toByte(), encoded[0])
        assertEquals(0x02.toByte(), encoded[255])
        assertEquals(0xAA.toByte(), encoded[256])
        assertArrayEquals(input, Cobs.decode(encoded))
    }

    @Test
    fun runsLongerThanTwoGroupsRoundTrip() {
        val input = ByteArray(508) { 0xAA.toByte() }
        val encoded = Cobs.encode(input)

        assertEquals(511, encoded.size)
        assertEquals(0xFF.toByte(), encoded[0])
        assertEquals(0xFF.toByte(), encoded[255])
        assertEquals(0x01.toByte(), encoded[510])
        assertArrayEquals(input, Cobs.decode(encoded))
    }

    @Test
    fun longRunOfZerosRoundTrips() {
        val input = ByteArray(1000)
        val encoded = Cobs.encode(input)

        assertEquals(1001, encoded.size)
        assertTrue(encoded.all { it == 0x01.toByte() })
        assertArrayEquals(input, Cobs.decode(encoded))
    }

    @Test
    fun roundTripsAssortedLengthsAndContents() {
        val random = Random(0xC0B5)
        for (size in intArrayOf(0, 1, 2, 3, 4, 10, 100, 253, 254, 255, 256, 300, 507, 508, 509, 1000)) {
            val input = ByteArray(size) {
                if (random.nextInt(4) == 0) 0 else random.nextInt(256).toByte()
            }
            val encoded = Cobs.encode(input)

            assertTrue("encoded output must never contain 0x00", encoded.none { it == 0.toByte() })
            assertArrayEquals("round trip for size $size", input, Cobs.decode(encoded))
        }
    }

    @Test
    fun trailingWireDelimiterIsNotPartOfTheBody() {
        // encode() must not append the transport's 0x00 delimiter...
        assertTrue(Cobs.encode(hex("112233")).none { it == 0.toByte() })
        // ...and decode() must not silently strip it: an embedded 0x00 is
        // malformed COBS, exactly as transport_cobs_decode treats it.
        assertThrows(IllegalArgumentException::class.java) {
            Cobs.decode(hex("0311223300"))
        }
    }

    @Test
    fun malformedInputIsRejected() {
        // Zero byte as the first code byte.
        assertThrows(IllegalArgumentException::class.java) { Cobs.decode(hex("00")) }
        // Code byte promises more data than the body contains.
        assertThrows(IllegalArgumentException::class.java) { Cobs.decode(hex("0311")) }
        // Code overruns the remaining input.
        assertThrows(IllegalArgumentException::class.java) { Cobs.decode(hex("051122")) }
        // Code byte with no following data at all.
        assertThrows(IllegalArgumentException::class.java) { Cobs.decode(hex("03")) }
    }

    private fun hex(value: String): ByteArray {
        if (value.isEmpty()) return ByteArray(0)
        require(value.length % 2 == 0) { "hex string must have even length: $value" }
        return ByteArray(value.length / 2) { index ->
            value.substring(index * 2, index * 2 + 2).toInt(16).toByte()
        }
    }

    private fun ByteArray.toHex(): String =
        joinToString(separator = "") { "%02x".format(it.toInt() and 0xFF) }
}
